export function toJsonCaptureDirective(value: CaptureDirective): Json {
    return {
        default: toJsonCaptureMode(value.default),
        rules: value.rules.map((item0) => toJsonCaptureRule(item0)),
    };
}

/** Return one CaptureDirective from one JSON value. */
export function fromJsonCaptureDirective(value: Json): CaptureDirective {
    const object = jsonObject(value);

    return {
        default: fromJsonCaptureMode(jsonField(object, "default")),
        rules: jsonArray(jsonField(object, "rules")).map((item0) => fromJsonCaptureRule(item0)),
    };
}

/** A capture rule keyed by name. */
export type CaptureRule = {
    /** The binding name to override. */
    readonly name: StringId;
    /** The capture mode to use for this binding. */
    readonly mode: CaptureMode;
};

export const CaptureRule = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: CaptureRule): void {
        encodeCaptureRule(writer, value);
    },

    /** Decode one CaptureRule. */
    decode(reader: BinaryReader): CaptureRule {
        return decodeCaptureRule(reader);
    },

    /** Return this value as JSON. */
    toJson(value: CaptureRule): Json {
        return toJsonCaptureRule(value);
    },

    /** Return one CaptureRule from one JSON value. */
    fromJson(value: Json): CaptureRule {
        return fromJsonCaptureRule(value);
    },
};

/** Encode one CaptureRule. */
export function encodeCaptureRule(writer: BinaryWriter, value: CaptureRule): void {
    encodeStringId(writer, value.name);
    encodeCaptureMode(writer, value.mode);
}

/** Decode one CaptureRule. */
export function decodeCaptureRule(reader: BinaryReader): CaptureRule {
    const name = decodeStringId(reader);
    const mode = decodeCaptureMode(reader);

    return {
        name,
        mode,
    };
}

/** Return one JSON value for one CaptureRule. */
export function toJsonCaptureRule(value: CaptureRule): Json {
    return {
        name: toJsonStringId(value.name),
        mode: toJsonCaptureMode(value.mode),
    };
}

/** Return one CaptureRule from one JSON value. */
export function fromJsonCaptureRule(value: Json): CaptureRule {
    const object = jsonObject(value);

    return {
        name: fromJsonStringId(jsonField(object, "name")),
        mode: fromJsonCaptureMode(jsonField(object, "mode")),
    };
}
